/**
 * Exo DURBIN driver: mirrors PolyBench/C durbin.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "durbin.h"

/* Include the Exo-generated kernel header. */
#include "generated/durbin/durbin.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      r[i] = (n+1-i);
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Levinson-Durbin recursion implemented in-place (no temporary z array).
# We then apply loop tiling and unrolling to improve ILP and locality.

@proc
def kernel_durbin_base(
    n: size,
    r: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    alpha: DATA_TYPE
    beta: DATA_TYPE
    sum: DATA_TYPE
    tmp_left: DATA_TYPE
    tmp_right: DATA_TYPE

    # Initial conditions for k = 0
    y[0] = -r[0]
    beta = 1.0
    alpha = -r[0]

    # Main Levinson-Durbin recursion
    for k in seq(1, n):
        # Update beta using previous reflection coefficient
        beta = (1.0 - alpha * alpha) * beta

        # Compute sum_{i=0}^{k-1} r[k-i-1] * y[i]
        sum = 0.0
        for i in seq(0, k):
            sum += r[k - i - 1] * y[i]

        # New reflection coefficient
        alpha = -(r[k] + sum) / beta

        # Symmetric in-place update of y[0..k-1].
        # Algebraically equivalent to:
        #   z[i] = y[i] + alpha * y[k-1-i]
        #   y[i] = z[i]
        # but avoids the temporary z array.
        for i in seq(0, k / 2):
            tmp_left = y[i]
            tmp_right = y[k - 1 - i]
            y[i] = tmp_left + alpha * tmp_right
            y[k - 1 - i] = tmp_right + alpha * tmp_left

        # When k is odd there is a middle element that pairs with itself.
        if k % 2 == 1:
            y[k / 2] = (1.0 + alpha) * y[k / 2]

        # Set the last element for this stage
        y[k] = alpha


# === Scheduling ===

# Start from the base kernel.
sched = kernel_durbin_base

# Normalize/simplify expressions before further transformations.
sched = simplify(sched)

# 1) Tile and unroll the inner reduction loop over i in the sum.
sum_i = sched.find_loop("i #0")
sched = divide_loop(sched, sum_i, 4, ("io_sum", "ii_sum"), tail="guard")
sched = unroll_loop(sched, sched.find_loop("ii_sum"))

# 2) Tile and unroll the symmetric in-place update loop over i.
update_i = sched.find_loop("i #0")
sched = divide_loop(sched, update_i, 2, ("io_upd", "ii_upd"), tail="guard")
sched = unroll_loop(sched, sched.find_loop("ii_upd"))

# Expose the scheduled kernel under the name expected by the C driver.
kernel_durbin = rename(sched, "kernel_durbin")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(r));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 1D views to raw pointers. */
  kernel_durbin(/*ctxt=*/NULL,
                n,
                (DATA_TYPE*)POLYBENCH_ARRAY(r),
                (DATA_TYPE*)POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(r);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}

