# Reference Durbin kernel (direct transcription of PolyBench-C)
# -----------------------------------------------------------------------------
@proc
def kernel_durbin_base(
    n: size,
    r: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    z: DATA_TYPE[n] @ DRAM
    alpha: DATA_TYPE
    beta: DATA_TYPE
    sum: DATA_TYPE

    # Initial conditions: match PolyBench reference implementation.
    y[0] = -r[0]
    beta = 1.0
    alpha = -r[0]

    for k in seq(1, n):
        # Recurrence for beta and alpha.
        beta = (1.0 - alpha * alpha) * beta
        sum = 0.0

        # Compute correlation sum:
        #   sum = sum_{i=0..k-1} r[k-i-1] * y[i]
        for i in seq(0, k):
            sum += r[k - i - 1] * y[i]

        alpha = -(r[k] + sum) / beta

        # Update temporary vector z using current y and alpha.
        for i in seq(0, k):
            z[i] = y[i] + alpha * y[k - i - 1]

        # Copy z back into y.
        for i in seq(0, k):
            y[i] = z[i]

        # Set the new endpoint.
        y[k] = alpha


